#!/usr/bin/env python3
"""Report measured frozen receipts; no patient training, tuning or synthetic results."""
import argparse,json,sys,hashlib,csv
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from self_audit.model import digest
from self_audit.engine import source_digest

p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);p.add_argument('--results',type=Path,required=True);a=p.parse_args()
methods=['supervised','supervised_extra','ema_full','ema_block'];summaries=[]
for method in methods:
 name=f'L8_S42_{method}_C256_B52_10000';run=a.root/'runs'/name;ev=a.root/'evaluation'/name
 if not (ev/'METRICS.json').is_file():continue
 report=json.loads((run/'REPORT.json').read_text());manifest=json.loads((run/'final/MANIFEST.json').read_text());recipe=json.loads((ev/'RECIPE.json').read_text());metrics=json.loads((ev/'METRICS.json').read_text())
 sha=digest(run/'final/MANIFEST.json')
 assert sha==report['final_manifest_sha256']==recipe['checkpoint_sha256']
 assert digest(run/'final/weights.pt')==manifest['payload_sha256']
 assert not report['synthetic'] and not metrics['synthetic'] and not report['label_reads_outside_budget']
 summary={'run':name,'method':method,'steps':report['steps'],'elapsed_seconds':report['elapsed_seconds'],'checkpoint_manifest_sha256':sha,'checkpoint_payload_sha256':manifest['payload_sha256'],'training_data_sha256':manifest['data_sha256'],'source_sha256':manifest['source_sha256'],'weights_sha256':manifest['backbone']['weights_sha256'],'evaluation_recipe_sha256':digest(ev/'RECIPE.json'),'metrics_sha256':digest(ev/'METRICS.json'),'macro_patient':metrics['macro_patient'],'pseudo_accepted':report['pseudo_accepted'],'label_budget':report['label_budget'],'prediction_model':manifest['prediction_model']}
 summaries.append(summary)
 (a.results/'logs'/(name+'_MEASURED.json')).write_text(json.dumps(summary,indent=2)+'\n')
status='EMA-block completed and scored; remaining matrix runs cancelled by user.' if len(summaries)==4 else 'EMA-block is still training; it will be scored and pushed, then all further runs stop.'
lines=['# ACDC measured results — stop after EMA-block','',status,'','Protocol: dense labeled TRAIN budget8 (audit included), subset seed42, initialization seed42, random crop256, ordinary batch52, FP32, 10,000 steps, fixed final student checkpoint. EMA is not independent truth.','', 'All scores below are patient-macro Dice on development-exposed VAL18 (%). No independent confirmation or clinical efficacy claim.','', '| Method | RV | MYO | LV | Timed hours | Accepted pseudo updates |','|---|---:|---:|---:|---:|---:|']
for r in summaries:
 vals=[100*r['macro_patient'][k]['dice'] for k in ['RV','MYO','LV']]
 lines.append(f"| {r['method']} | {vals[0]:.2f} | {vals[1]:.2f} | {vals[2]:.2f} | {r['elapsed_seconds']/3600:.2f} | {r['pseudo_accepted']} |")
lines += ['',f'Completed and scored: {len(summaries)}/4 retained methods. Each result uses one label-subset seed and one initialization seed; across-seed standard deviations are unavailable. Timed hours cover the training loop/final save and exclude startup/data hashing; they are not billed reservation cost or optimized latency. EMA-block includes diagnostic audit/JVP work and is not an optimized baseline latency measurement.','', '## Scope and missing evidence','', 'The five allocation/guard arms (joint_guard, independent_guard, sign, joint_no_class, joint_no_guard), other label budgets/subset seeds and TEST inference are cancelled by the user. No result establishes superiority of Self-Audit v2: its full guarded experiments were not executed. Native batch16 was previously stopped at step1515; its checkpoint/logs remain preserved and were not exactly resumed.','', 'Frozen checkpoint, payload, pretrained weight, executed-source, training-data and metric hashes are recorded per completed run in logs/*_MEASURED.json. CSVs contain classwise confusion, IoU, precision, recall and patient metrics. Patient Dice averages available reference-frame Dice; pooled-frame statistics are named explicitly. Undefined absent-reference Dice/IoU remain blank with explicit FP counts.','', 'No TEST Dice, HD95, multi-seed uncertainty, patient bootstrap, modern external SSL baseline or independent-confirmation result exists. HD95 geometry/implementation remain uncertified. VAL18 is exposed development data. The original TRAIN80/VAL20 split has a duplicate TRAIN/VAL cine; reviewed TRAIN80/VAL18 metadata was reused as directed by the runbook, leaving all raw files and TRAIN IDs unchanged.','', '## Data, initialization and paths','', 'Drive: KhanhDrive:Dataset/ACDC; raw local data: /workspace/self-audit-v2/data/raw/ACDC. All 1,053 files (7.269 GiB) matched remote checksums. All nine 4/8/16 × 42/123/2026 preparation caches completed, with zero U-mask reads. DATA_PREPARATION.csv records actual labeled frames/slices: L8/S42 has 16 frames and 154 slices. Crops are geometry-only and aligned; padding is ignored by supervised, audit and pseudo losses. VAL scoring uses full native cines. TEST GT filenames on Drive were never used for training or scoring.','', 'Reviewed split SHA256: b826eaf494760079aa559b0c0c12f7444951d779ebbb5ed291c0398f20bf835f. Pretrained weight SHA256: 21b726bb286e037f00a23fb4699fa9bda9c75b6a615bd57ce3013cec1b528d54, from the user-authorized jaychempan Hugging Face mirror. Mirror LFS and official short hash match; full independent official upstream certification is unavailable. Official source is clean at 6876159a11b4df116f30f667f8c9888617df0751. No random fallback, external license acceptance or historical trainer/weights were used. Reviewed split metadata alone came from the archive.','', 'Source worktree: /root/Self-Audit-vram24. Executed training-source SHA256: '+source_digest()+'. Runs, checkpoints, raw logs, full frozen probabilities and patient overlays remain under /workspace/self-audit-v2/vram24 or local ignored files. Only compact tables/receipts and aggregate figures are committed.','', '## Verification and figures','', 'python scripts/check_repo.py and python -m pytest -q are required by the finalization script before the final Git push. Last completed CPU-isolated checks (CUDA_VISIBLE_DEVICES empty): PASS, 58 passed, one TorchScript deprecation warning; final receipts are recorded in logs/FINAL_CHECKS.json when available. Manufactured tests are software evidence, not patient accuracy evidence.','', 'Aggregate confusion matrices, patient Dice boxplots, loss/acceptance/VRAM curves, ablation and accuracy/cost summaries are retained. Patient image overlays/probability maps stay local and are excluded from Git. No VAL learning curve exists because only final checkpoints were scored. Full source/config/command receipts and prior real pilot capacity measurements remain in this branch.','', 'ACDC: O. Bernard et al., IEEE TMI 37(11), 2514–2525 (2018), doi:10.1109/TMI.2018.2837502.','']
(a.results/'REPORT.md').write_text('\n'.join(lines))
(a.results/'logs/COMPLETED_SUMMARY.json').write_text(json.dumps({'completed_methods':summaries,'planned_stop_after':'ema_block','test_inference_cancelled':True},indent=2)+'\n')
